using FMODUnity;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceTier", menuName = "Data/Battle/Dice System/DiceTier")]
public class DiceTier : ScriptableObject
{
	[Header("Tier Icon")]
	[SerializeField]
	private bool enableTierIcon;

	[SerializeField]
	[ShowIf("enableTierIcon")]
	private Sprite tierIcon;

	[Header("Dice Name")]
	[SerializeField]
	private int diceNameStarAmount;

	[SerializeField]
	private bool addDiceStringToTheEndOfName;

	[SerializeField]
	private bool sentinel;

	[SerializeField]
	private bool enemy;

	[Header("2D")]
	[SerializeField]
	private Sprite doubleActionFramSprite;

	[Header("3D")]
	[SerializeField]
	private Mesh diceMesh;

	[SerializeField]
	private GameObject dice3DPrefab;

	[Header("3D Dice Trail")]
	[SerializeField]
	private GameObject diceTrailPrefab;

	[Header("Misc")]
	[SerializeField]
	private Color diceColor;

	[SerializeField]
	private string diceTierID;

	[SerializeField]
	private bool enableDiceRewardBackgroundColor;

	[SerializeField]
	[ShowIf("enableDiceRewardBackgroundColor")]
	private Color diceRewardBackgroundColor;

	[Header("Reward")]
	[SerializeField]
	private bool enableRewardPrefab;

	[SerializeField]
	[ShowIf("enableRewardPrefab")]
	private GameObject rewardPrefab;

	[SerializeField]
	private bool enableCustomGainDiceSFX;

	[SerializeField]
	[ShowIf("enableCustomGainDiceSFX")]
	private EventReference gainDiceSFX;

	[Header("Preview")]
	[SerializeField]
	private Sprite backgroundSprite;

	[SerializeField]
	private bool enableCardDetailPrefab;

	[SerializeField]
	[ShowIf("enableCardDetailPrefab")]
	private GameObject cardDetailPrefab;

	public Sprite TierIcon => tierIcon;

	public bool AddDiceStringToTheEndOfName => addDiceStringToTheEndOfName;

	public bool Sentinel => sentinel;

	public bool Enemy => enemy;

	public Sprite DoubleActionFrameSprite => doubleActionFramSprite;

	public Mesh DiceMesh => diceMesh;

	public GameObject Dice3DPrefab => dice3DPrefab;

	public GameObject DiceTrailPrefab => diceTrailPrefab;

	public Color DiceColor => diceColor;

	public string DiceTierID => diceTierID;

	private string DiceTierIDWithDie => diceTierID + "Die";

	public Color DiceRewardBackgroundColor => diceRewardBackgroundColor;

	public GameObject RewardPrefab => rewardPrefab;

	public bool EnableCustomGainDiceSFX => enableCustomGainDiceSFX;

	public EventReference GainDiceSFX => gainDiceSFX;

	public Sprite BackgroundSprite => backgroundSprite;

	public bool EnableCardDetailPrefab => enableCardDetailPrefab;

	public GameObject CardDetailPrefab => cardDetailPrefab;

	public string GetDiceNameWithStars(string diceName)
	{
		for (int i = 0; i < diceNameStarAmount; i++)
		{
			diceName += "+";
		}
		return diceName;
	}

	public string GetLocalizedDiceTier()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(DiceTierID);
	}

	public string GetLocalizedDiceTierWithDie()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(DiceTierIDWithDie);
	}
}
